custom_fields.content:
[[[
const a = entity?.attributes ?? {};
const matchTeams = String(a.match ?? '').split(' vs ');
const isHome = a.home_away === 'Home';
const fallbackName = String(a.friendly_name ?? 'FotMob Team').replace(/\s+Match$/, '');
const teamName = a.team_name || (matchTeams.length === 2 ? (isHome ? matchTeams[0] : matchTeams[1]) : fallbackName);
const leagueName = a.league || states['sensor.your_team_league_table']?.attributes?.league_name || 'League';
const logo = a.entity_picture ?? '';
const position = states['sensor.your_team_position']?.state ?? '—';
const points = states['sensor.your_team_points']?.state ?? '—';
const played = states['sensor.your_team_played']?.state ?? '—';
const form = String(states['sensor.your_team_form']?.state ?? '').split('-').filter(Boolean);
const colors = {W:'#34d399',D:'#fbbf24',L:'#fb7185'};
const chips = form.slice(-5).map(v => '<span style="display:grid;place-items:center;width:28px;height:28px;border-radius:10px;background:' + (colors[v] ?? '#64748b') + ';color:#fff;font-size:12px;font-weight:900;box-shadow:0 6px 16px rgba(15,23,42,.18);">' + v + '</span>').join('');
return '<div style="position:relative;isolation:isolate;min-height:230px;padding:28px;color:white;display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:28px;">' +
  '<div style="position:absolute;z-index:-1;right:-70px;top:-100px;width:280px;height:280px;border-radius:50%;background:rgba(255,255,255,.10);"></div>' +
  '<div style="position:absolute;z-index:-1;left:35%;bottom:-130px;width:260px;height:260px;border-radius:50%;background:rgba(255,255,255,.07);"></div>' +
  '<div style="display:flex;align-items:center;gap:20px;min-width:260px;">' +
    '<div style="width:104px;height:104px;border-radius:28px;background:rgba(255,255,255,.95);display:grid;place-items:center;box-shadow:0 18px 40px rgba(15,23,42,.25);"><img src="' + logo + '" style="width:78px;height:78px;object-fit:contain;"></div>' +
    '<div><div style="font-size:12px;font-weight:800;letter-spacing:.18em;text-transform:uppercase;opacity:.75;">' + leagueName + '</div><div style="margin-top:5px;font-size:clamp(26px,4vw,42px);font-weight:900;line-height:1;letter-spacing:-.04em;">' + teamName + '</div><div style="margin-top:10px;font-size:13px;opacity:.78;">FotMob live dashboard</div></div>' +
  '</div>' +
  '<div style="display:grid;grid-template-columns:repeat(3,minmax(78px,1fr));gap:10px;min-width:min(100%,330px);">' +
    '<div style="padding:14px;border-radius:18px;background:rgba(255,255,255,.12);backdrop-filter:blur(12px);"><div style="font-size:11px;opacity:.72;text-transform:uppercase;letter-spacing:.08em;">Loc</div><div style="margin-top:4px;font-size:28px;font-weight:900;">#' + position + '</div></div>' +
    '<div style="padding:14px;border-radius:18px;background:rgba(255,255,255,.12);backdrop-filter:blur(12px);"><div style="font-size:11px;opacity:.72;text-transform:uppercase;letter-spacing:.08em;">Puncte</div><div style="margin-top:4px;font-size:28px;font-weight:900;">' + points + '</div></div>' +
    '<div style="padding:14px;border-radius:18px;background:rgba(255,255,255,.12);backdrop-filter:blur(12px);"><div style="font-size:11px;opacity:.72;text-transform:uppercase;letter-spacing:.08em;">Meciuri</div><div style="margin-top:4px;font-size:28px;font-weight:900;">' + played + '</div></div>' +
    '<div style="grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 14px;border-radius:18px;background:rgba(15,23,42,.18);"><span style="font-size:11px;text-transform:uppercase;letter-spacing:.10em;font-weight:800;opacity:.78;">Forma recentă</span><div style="display:flex;gap:7px;">' + chips + '</div></div>' +
  '</div>' +
'</div>';
]]]

[[[
const a = entity?.attributes ?? {};
const opponent = a.opponent ?? 'Adversar';
const isHome = a.home_away === 'Home';
const matchTeams = String(a.match ?? '').split(' vs ');
const fallbackName = String(entity?.attributes?.friendly_name ?? 'FotMob Team').replace(/\s+Match$/, '');
const teamName = a.team_name || (matchTeams.length === 2 ? (isHome ? matchTeams[0] : matchTeams[1]) : fallbackName);
const teamLogo = a.entity_picture ?? '';
const opponentLogo = a.opponent_logo ?? '';
const homeName = isHome ? teamName : opponent;
const awayName = isHome ? opponent : teamName;
const homeLogo = isHome ? teamLogo : opponentLogo;
const awayLogo = isHome ? opponentLogo : teamLogo;
const center = a.score || 'VS';
const live = a.status === 'Live';
const difficultyColor = a.difficulty === 'High' ? '#ef4444' : (a.difficulty === 'Medium' ? '#f59e0b' : '#22c55e');
const formColors = {W:'#22c55e',D:'#f59e0b',L:'#ef4444'};
const oppForm = (a.opponent_form ?? []).map(v => '<span style="display:grid;place-items:center;width:22px;height:22px;border-radius:7px;background:' + (formColors[v] ?? '#64748b') + ';color:#fff;font-size:10px;font-weight:900;">' + v + '</span>').join('');
return '<div style="padding:20px;">' +
 '<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:20px;"><div><div style="font-size:11px;font-weight:850;letter-spacing:.12em;text-transform:uppercase;color:#8b5cf6;">Următorul meci</div><div style="margin-top:4px;font-size:19px;font-weight:850;">' + (a.league || 'SuperLiga') + '</div></div><span style="padding:7px 10px;border-radius:999px;background:' + (live ? '#ef444422' : '#8b5cf622') + ';color:' + (live ? '#ef4444' : '#8b5cf6') + ';font-size:10px;font-weight:900;letter-spacing:.08em;">' + (live ? 'LIVE' : 'PROGRAMAT') + '</span></div>' +
 '<div style="display:grid;grid-template-columns:minmax(0,1fr) 90px minmax(0,1fr);align-items:center;gap:10px;">' +
   '<div style="text-align:center;min-width:0;"><img src="' + homeLogo + '" style="width:64px;height:64px;object-fit:contain;"><div style="margin-top:8px;font-weight:850;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + homeName + '</div><div style="margin-top:3px;font-size:10px;color:var(--secondary-text-color);font-weight:700;">ACASĂ</div></div>' +
   '<div style="text-align:center;"><div style="font-size:27px;font-weight:950;letter-spacing:-.04em;">' + center + '</div><div style="margin-top:7px;font-size:11px;line-height:1.35;color:var(--secondary-text-color);">' + (a.timestamp ?? '—') + '</div></div>' +
   '<div style="text-align:center;min-width:0;"><img src="' + awayLogo + '" style="width:64px;height:64px;object-fit:contain;"><div style="margin-top:8px;font-weight:850;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + awayName + '</div><div style="margin-top:3px;font-size:10px;color:var(--secondary-text-color);font-weight:700;">DEPLASARE</div></div>' +
 '</div>' +
 '<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:20px;padding-top:15px;border-top:1px solid var(--divider-color);"><div style="display:flex;align-items:center;gap:7px;">' + oppForm + '</div><div style="display:flex;align-items:center;gap:8px;font-size:11px;font-weight:750;"><span>Loc adversar #' + (a.opponent_rank ?? '—') + '</span><span style="width:7px;height:7px;border-radius:50%;background:' + difficultyColor + ';"></span><span>' + (a.difficulty ?? '—') + '</span></div></div>' +
'</div>';
]]]

[[[
const games = Array.isArray(entity?.attributes?.form_list) ? entity.attributes.form_list.slice(-5).reverse() : [];
const colors = {W:'#22c55e',D:'#f59e0b',L:'#ef4444'};
const rows = games.map(game => {
 const home = game?.home ?? {}; const away = game?.away ?? {};
 const isHome = Boolean(home.isOurTeam);
 const opponent = (isHome ? away.name : home.name) ?? 'Necunoscut';
 const result = game?.resultString ?? '?';
 const date = game?.tooltipText?.utcTime ? new Date(game.tooltipText.utcTime).toLocaleDateString('ro-RO',{day:'2-digit',month:'short'}) : '';
 return '<div style="display:grid;grid-template-columns:32px 34px minmax(0,1fr) auto;align-items:center;gap:10px;padding:11px 0;border-top:1px solid var(--divider-color);">' +
  '<span style="display:grid;place-items:center;width:28px;height:28px;border-radius:9px;background:' + (colors[result] ?? '#64748b') + ';color:white;font-size:11px;font-weight:950;">' + result + '</span>' +
  '<img src="' + (game?.imageUrl ?? '') + '" style="width:28px;height:28px;object-fit:contain;">' +
  '<div style="min-width:0;text-align:left;"><div style="font-weight:800;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + opponent + '</div><div style="margin-top:2px;color:var(--secondary-text-color);font-size:10px;">' + (isHome ? 'Acasă' : 'Deplasare') + (date ? ' · ' + date : '') + '</div></div>' +
  '<div style="font-size:15px;font-weight:900;font-variant-numeric:tabular-nums;">' + (game?.score ?? '—') + '</div></div>';
}).join('');
return '<div style="padding:20px;"><div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;"><div><div style="font-size:11px;font-weight:850;letter-spacing:.12em;text-transform:uppercase;color:#22c55e;">Rezultate</div><div style="margin-top:4px;font-size:19px;font-weight:850;">Forma recentă</div></div><ha-icon icon="mdi:chart-timeline-variant-shimmer" style="color:#22c55e;"></ha-icon></div>' + (rows || '<div style="padding:20px 0;color:var(--secondary-text-color);">Nu există meciuri recente.</div>') + '</div>';
]]]

[[[
const value = String(entity?.state ?? 'N/A');
const cut = value.lastIndexOf(' (');
const player = cut > 0 ? value.slice(0, cut) : value;
const stat = cut > 0 ? value.slice(cut + 2, -1) : '—';
return '<div style="display:grid;grid-template-columns:54px minmax(0,1fr);align-items:center;gap:14px;padding:16px 18px;">' +
  '<div style="width:52px;height:52px;border-radius:17px;display:grid;place-items:center;background:#f59e0b20;color:#f59e0b;"><ha-icon icon="mdi:soccer" style="width:28px;height:28px;"></ha-icon></div>' +
  '<div style="min-width:0;text-align:left;"><div style="font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:var(--secondary-text-color);font-weight:800;">Golgheter</div><div style="margin-top:5px;font-size:16px;font-weight:800;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + player + '</div><div style="margin-top:4px;color:#f59e0b;font-size:12px;font-weight:800;">' + stat + '</div></div>' +
'</div>';
]]]

[[[
const value = String(entity?.state ?? 'N/A');
const cut = value.lastIndexOf(' (');
const player = cut > 0 ? value.slice(0, cut) : value;
const stat = cut > 0 ? value.slice(cut + 2, -1) : '—';
return '<div style="display:grid;grid-template-columns:54px minmax(0,1fr);align-items:center;gap:14px;padding:16px 18px;">' +
  '<div style="width:52px;height:52px;border-radius:17px;display:grid;place-items:center;background:#06b6d420;color:#06b6d4;"><ha-icon icon="mdi:shoe-cleat" style="width:28px;height:28px;"></ha-icon></div>' +
  '<div style="min-width:0;text-align:left;"><div style="font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:var(--secondary-text-color);font-weight:800;">Pase decisive</div><div style="margin-top:5px;font-size:16px;font-weight:800;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + player + '</div><div style="margin-top:4px;color:#06b6d4;font-size:12px;font-weight:800;">' + stat + '</div></div>' +
'</div>';
]]]

[[[
const value = String(entity?.state ?? 'N/A');
const cut = value.lastIndexOf(' (');
const player = cut > 0 ? value.slice(0, cut) : value;
const stat = cut > 0 ? value.slice(cut + 2, -1) : '—';
return '<div style="display:grid;grid-template-columns:54px minmax(0,1fr);align-items:center;gap:14px;padding:16px 18px;">' +
  '<div style="width:52px;height:52px;border-radius:17px;display:grid;place-items:center;background:#8b5cf620;color:#8b5cf6;"><ha-icon icon="mdi:star-circle" style="width:28px;height:28px;"></ha-icon></div>' +
  '<div style="min-width:0;text-align:left;"><div style="font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:var(--secondary-text-color);font-weight:800;">Cel mai bun rating</div><div style="margin-top:5px;font-size:16px;font-weight:800;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + player + '</div><div style="margin-top:4px;color:#8b5cf6;font-size:12px;font-weight:800;">' + stat + '</div></div>' +
'</div>';
]]]

[[[
const table = Array.isArray(entity?.attributes?.table) ? entity.attributes.table : [];
const teamName = table.find(row => row.is_current)?.team ?? 'Your team';
const resultColors = {W:'#22c55e',D:'#f59e0b',L:'#ef4444'};
const rows = table.map(row => {
 const form = (row.form ?? []).map(v => '<span style="display:inline-block;width:7px;height:7px;border-radius:50%;background:' + (resultColors[v] ?? '#64748b') + ';margin-left:3px;"></span>').join('');
 return '<div style="min-width:650px;display:grid;grid-template-columns:38px minmax(180px,1fr) 40px 40px 40px 58px 48px 82px;align-items:center;gap:8px;padding:10px 12px;border-top:1px solid var(--divider-color);' + (row.is_current ? 'background:rgba(124,58,237,.13);box-shadow:inset 3px 0 #8b5cf6;border-radius:9px;' : '') + '">' +
  '<div style="font-weight:900;color:' + (row.is_current ? '#8b5cf6' : 'var(--secondary-text-color)') + ';">' + row.rank + '</div>' +
  '<div style="display:flex;align-items:center;gap:9px;min-width:0;"><img src="https://images.fotmob.com/image_resources/logo/teamlogo/' + row.team_id + '.png" style="width:24px;height:24px;object-fit:contain;"><span style="font-weight:' + (row.is_current ? '900' : '700') + ';overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + row.team + '</span></div>' +
  '<div>' + row.played + '</div><div>' + row.wins + '</div><div>' + row.draws + '</div><div>' + row.goals + '</div><div style="font-weight:900;">' + row.pts + '</div><div style="white-space:nowrap;">' + form + '</div></div>';
}).join('');
return '<div style="padding:20px;"><div style="display:flex;align-items:end;justify-content:space-between;gap:14px;margin-bottom:16px;"><div><div style="font-size:11px;font-weight:850;letter-spacing:.12em;text-transform:uppercase;color:#3b82f6;">Clasament live</div><div style="margin-top:4px;font-size:21px;font-weight:900;">' + (entity?.attributes?.league_name ?? 'Liga I') + '</div></div><div style="padding:8px 12px;border-radius:14px;background:#8b5cf618;color:#8b5cf6;font-size:12px;font-weight:900;">' + teamName + ' #' + entity.state + '</div></div>' +
 '<div style="overflow-x:auto;padding-bottom:4px;"><div style="min-width:650px;display:grid;grid-template-columns:38px minmax(180px,1fr) 40px 40px 40px 58px 48px 82px;gap:8px;padding:0 12px 10px;color:var(--secondary-text-color);font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase;"><span>#</span><span>Echipa</span><span>M</span><span>V</span><span>E</span><span>Goluri</span><span>Pct</span><span>Formă</span></div>' + rows + '</div></div>';
]]]

[[[
const stadium = states['sensor.your_team_stadium'];
const coach = states['sensor.your_team_coach'];
const history = states['sensor.your_team_history'];
const arrivals = Array.isArray(entity?.attributes?.players_in) ? entity.attributes.players_in.slice(0,4) : [];
const trophies = Array.isArray(history?.attributes?.trophies) ? history.attributes.trophies : [];
const arrivalsHtml = arrivals.map(p => '<div style="display:grid;grid-template-columns:36px minmax(0,1fr);gap:10px;align-items:center;padding:10px 0;border-top:1px solid var(--divider-color);"><div style="width:34px;height:34px;border-radius:11px;display:grid;place-items:center;background:#22c55e18;color:#22c55e;"><ha-icon icon="mdi:arrow-down-bold" style="width:18px;"></ha-icon></div><div style="min-width:0;text-align:left;"><div style="font-weight:800;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + (p.name ?? 'Necunoscut') + '</div><div style="margin-top:2px;font-size:10px;color:var(--secondary-text-color);">' + (p.fromClub ?? '—') + ' · ' + (p.fee?.feeText ?? '—') + '</div></div></div>').join('');
const trophyHtml = trophies.map(t => '<div style="padding:11px 12px;border-radius:14px;background:#f59e0b12;"><div style="font-size:11px;color:#f59e0b;font-weight:900;text-transform:uppercase;">' + t.name + '</div><div style="margin-top:4px;font-size:21px;font-weight:950;">' + t.count + '</div></div>').join('');
return '<div style="padding:20px;">' +
 '<div><div style="font-size:11px;font-weight:850;letter-spacing:.12em;text-transform:uppercase;color:#f59e0b;">Identitate</div><div style="margin-top:4px;font-size:20px;font-weight:900;">Club & transferuri</div></div>' +
 '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:16px;">' +
  '<div style="padding:14px;border-radius:17px;background:var(--secondary-background-color);"><ha-icon icon="mdi:stadium" style="color:#22c55e;"></ha-icon><div style="margin-top:10px;font-size:13px;font-weight:850;">' + (stadium?.state ?? '—') + '</div><div style="margin-top:3px;font-size:10px;color:var(--secondary-text-color);">' + (stadium?.attributes?.city ?? '—') + ' · ' + (stadium?.attributes?.capacity ?? '—') + ' locuri</div></div>' +
  '<div style="padding:14px;border-radius:17px;background:var(--secondary-background-color);"><ha-icon icon="mdi:account-tie" style="color:#8b5cf6;"></ha-icon><div style="margin-top:10px;font-size:13px;font-weight:850;">' + (coach?.state ?? '—') + '</div><div style="margin-top:3px;font-size:10px;color:var(--secondary-text-color);">Antrenor · ' + (coach?.attributes?.age ?? '—') + ' ani</div></div>' +
 '</div>' +
 '<div style="margin-top:20px;font-size:12px;font-weight:900;text-transform:uppercase;letter-spacing:.08em;">Sosiri recente</div>' + (arrivalsHtml || '<div style="padding:14px 0;color:var(--secondary-text-color);">Nicio sosire.</div>') +
 '<div style="margin-top:20px;font-size:12px;font-weight:900;text-transform:uppercase;letter-spacing:.08em;">Trofee · ' + (history?.state ?? '—') + '</div><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-top:10px;">' + trophyHtml + '</div>' +
'</div>';
]]]
